const selectedDate = '2026-03-25';  // ✅ تاریخ دیگری

return {
  date: selectedDate,
  startTime: `${selectedDate}T00:00:00`,
  endTime: `${selectedDate}T23:59:59`
};

const input = $input.all();
const records = input.map(item => item.json || item).filter(r => r);

// ===== KPI =====
const grouped = {};
records.forEach(row => {
  const date = row.created_at.split('T')[0];
  if (!grouped[date]) {
    grouped[date] = { date, total_leads: 0, won_leads: 0 };
  }
  grouped[date].total_leads++;
  if (row.status === 'Won') grouped[date].won_leads++;
});

const kpi = Object.values(grouped)[0];
const conversion_rate = Math.round((kpi.won_leads / kpi.total_leads) * 10000) / 100;

// ===== SEGMENTS =====
const bySource = {}, byRep = {}, byType = {}, byCity = {};

records.forEach(row => {
  // Source
  if (!bySource[row.source]) {
    bySource[row.source] = { segment_type: 'source', segment_value: row.source, current_leads: 0, current_won: 0 };
  }
  bySource[row.source].current_leads++;
  if (row.status === 'Won') bySource[row.source].current_won++;

  // Rep
  if (!byRep[row.sales_rep]) {
    byRep[row.sales_rep] = { segment_type: 'sales_rep', segment_value: row.sales_rep, current_leads: 0, current_won: 0 };
  }
  byRep[row.sales_rep].current_leads++;
  if (row.status === 'Won') byRep[row.sales_rep].current_won++;

  // Type
  if (!byType[row.lead_type]) {
    byType[row.lead_type] = { segment_type: 'lead_type', segment_value: row.lead_type, current_leads: 0, current_won: 0 };
  }
  byType[row.lead_type].current_leads++;
  if (row.status === 'Won') byType[row.lead_type].current_won++;

  // City
  if (!byCity[row.city]) {
    byCity[row.city] = { segment_type: 'city', segment_value: row.city, current_leads: 0, current_won: 0 };
  }
  byCity[row.city].current_leads++;
  if (row.status === 'Won') byCity[row.city].current_won++;
});

const allSegments = [
  ...Object.values(bySource),
  ...Object.values(byRep),
  ...Object.values(byType),
  ...Object.values(byCity)
].map(s => ({
  ...s,
  current_conversion: Math.round((s.current_won / s.current_leads) * 10000) / 100
}));

// ===== FUNNEL =====
const totalLeads = records.length;
const contacted = records.filter(r => ['Contacted', 'Qualified', 'Proposal', 'Won'].includes(r.stage)).length;
const qualified = records.filter(r => ['Qualified', 'Proposal', 'Won'].includes(r.stage)).length;
const proposal = records.filter(r => ['Proposal', 'Won'].includes(r.stage)).length;
const won = records.filter(r => r.status === 'Won').length;

const funnel = [
  { stage: 'Lead', total_at_stage: totalLeads, moved_to_next: contacted, conversion_rate: Math.round((contacted / totalLeads) * 10000) / 100 },
  { stage: 'Contacted', total_at_stage: contacted, moved_to_next: qualified, conversion_rate: contacted > 0 ? Math.round((qualified / contacted) * 10000) / 100 : 0 },
  { stage: 'Qualified', total_at_stage: qualified, moved_to_next: proposal, conversion_rate: qualified > 0 ? Math.round((proposal / qualified) * 10000) / 100 : 0 },
  { stage: 'Proposal', total_at_stage: proposal, moved_to_next: won, conversion_rate: proposal > 0 ? Math.round((won / proposal) * 10000) / 100 : 0 }
];

// ===== MERGE ALL =====
return {
  snapshot_date: '2026-03-25',  // ✅ عوض شد
  total_leads: kpi.total_leads,
  won_leads: kpi.won_leads,
  conversion_rate: conversion_rate,
  segments_by_source: JSON.stringify(allSegments.filter(s => s.segment_type === 'source')),
  segments_by_rep: JSON.stringify(allSegments.filter(s => s.segment_type === 'sales_rep')),
  segments_by_type: JSON.stringify(allSegments.filter(s => s.segment_type === 'lead_type')),
  segments_by_city: JSON.stringify(allSegments.filter(s => s.segment_type === 'city')),
  funnel_stages: JSON.stringify(funnel)
};

const today = $node['KPI_Seg_Funnel'].json;
const yesterday = $input.all()[0].json;

const conversionChange = ((today.conversion_rate - yesterday.conversion_rate) / yesterday.conversion_rate) * 100;

return {
  today,
  yesterday,
  conversionChange: Math.round(conversionChange * 100) / 100,
  shouldAlert: conversionChange <= -10
};

const comp = $input.all()[0].json;

// Parse segments
const parseJSON = (str) => {
  try {
    return typeof str === 'string' ? JSON.parse(str) : str;
  } catch {
    return [];
  }
};

const todaySource = parseJSON(comp.today.segments_by_source);
const yesterdaySource = parseJSON(comp.yesterday.segments_by_source);
const todayRep = parseJSON(comp.today.segments_by_rep);
const yesterdayRep = parseJSON(comp.yesterday.segments_by_rep);
const todayType = parseJSON(comp.today.segments_by_type);
const yesterdayType = parseJSON(comp.yesterday.segments_by_type);
const todayCity = parseJSON(comp.today.segments_by_city);
const yesterdayCity = parseJSON(comp.yesterday.segments_by_city);
const todayFunnel = parseJSON(comp.today.funnel_stages);
const yesterdayFunnel = parseJSON(comp.yesterday.funnel_stages);

// Function to calculate ABSOLUTE changes
const calcChanges = (today, yesterday) => {
  return today.map(t => {
    const y = yesterday.find(x => x.segment_value === t.segment_value) || {};
    const change = t.current_conversion - (y.current_conversion || 0);
    return { ...t, previous_conversion: y.current_conversion || 0, change: Math.round(change * 100) / 100 };
  });
};

// Calculate all changes
const sourceChanges = calcChanges(todaySource, yesterdaySource);
const repChanges = calcChanges(todayRep, yesterdayRep);
const typeChanges = calcChanges(todayType, yesterdayType);
const cityChanges = calcChanges(todayCity, yesterdayCity);

// Find worst in each category
const worstSource = sourceChanges.sort((a, b) => a.change - b.change)[0];
const worstRep = repChanges.sort((a, b) => a.change - b.change)[0];
const worstType = typeChanges.sort((a, b) => a.change - b.change)[0];
const worstCity = cityChanges.sort((a, b) => a.change - b.change)[0];

// Analyze funnel (absolute)
const funnelAnalysis = todayFunnel.map(t => {
  const y = yesterdayFunnel.find(x => x.stage === t.stage) || {};
  const change = t.conversion_rate - (y.conversion_rate || 0);
  return { ...t, previous_rate: y.conversion_rate || 0, change: Math.round(change * 100) / 100 };
});

const worstFunnel = funnelAnalysis.sort((a, b) => a.change - b.change)[0];

// Helper function for 2 decimals
const fmt = (num) => Math.round(num * 100) / 100;

// Build message
const msg = `🚨 هشدار CRM

📊 کاهش کلی: ${fmt(comp.today.conversion_rate - comp.yesterday.conversion_rate)}%
امروز: ${fmt(comp.today.conversion_rate)}% | دیروز: ${fmt(comp.yesterday.conversion_rate)}%

📌 ضعیف‌ترین منبع:
${worstSource.segment_value}: ${worstSource.change > 0 ? '+' : ''}${fmt(worstSource.change)}%
(امروز: ${fmt(worstSource.current_conversion)}% | دیروز: ${fmt(worstSource.previous_conversion)}%)

👤 فروشنده با کم‌ترین عملکرد:
${worstRep.segment_value}: ${worstRep.change > 0 ? '+' : ''}${fmt(worstRep.change)}%
(امروز: ${fmt(worstRep.current_conversion)}% | دیروز: ${fmt(worstRep.previous_conversion)}%)

🏷️ نوع لید با کم‌ترین تبدیل:
${worstType.segment_value}: ${worstType.change > 0 ? '+' : ''}${fmt(worstType.change)}%
(امروز: ${fmt(worstType.current_conversion)}% | دیروز: ${fmt(worstType.previous_conversion)}%)

📍 شهر با کم‌ترین تبدیل:
${worstCity.segment_value}: ${worstCity.change > 0 ? '+' : ''}${fmt(worstCity.change)}%
(امروز: ${fmt(worstCity.current_conversion)}% | دیروز: ${fmt(worstCity.previous_conversion)}%)

🔻 ضعیف‌ترین مرحله فروش:
${worstFunnel.stage}: ${worstFunnel.change > 0 ? '+' : ''}${fmt(worstFunnel.change)}%
(امروز: ${fmt(worstFunnel.conversion_rate)}% | دیروز: ${fmt(worstFunnel.previous_rate)}%)`;

return { message: msg };
